async def handle_ssh_key_lookup(request: web.Request) -> web.Response:
    """GET /api/auth/ssh-key/{fingerprint} — look up user by SSH key fingerprint.

    Returns {user_id, is_guest} or 404. Never returns a JWT.
    JWT issuance happens via POST /api/auth/session after wish verifies key possession.
    """
    fingerprint = request.match_info["fingerprint"]
    conn = request.app[DB_CONN]
    key_row = get_ssh_key_by_fingerprint(conn, fingerprint)
    if not key_row:
        return web.json_response({"error": "SSH key not found"}, status=404)
    user = get_user_by_id(conn, key_row["user_id"])
    if not user:
        return web.json_response({"error": "SSH key not found"}, status=404)
    update_ssh_key_last_used(conn, fingerprint)
    return web.json_response({"user_id": user["id"], "is_guest": bool(user["is_guest"])})

def get_ssh_keys(conn: sqlite3.Connection, user_id: str) -> list[sqlite3.Row]:
    return conn.execute(
        "SELECT * FROM ssh_keys WHERE user_id = ? ORDER BY created_at ASC",
        (user_id,),
    ).fetchall()

def get_ssh_key_by_fingerprint(conn: sqlite3.Connection, fingerprint: str) -> sqlite3.Row | None:
    return conn.execute(
        "SELECT * FROM ssh_keys WHERE fingerprint = ?", (fingerprint,)
    ).fetchone()

func makePublicKeyAuth(cfg SSHServerConfig) ssh.PublicKeyHandler {
	client := &http.Client{Timeout: 10 * time.Second}

	return func(ctx ssh.Context, key ssh.PublicKey) bool {
		fp := gossh.FingerprintSHA256(key)
		ctx.SetValue(ctxKeyFingerprint, fp)

		// Try to look up existing user by fingerprint
		userID, found, err := lookupSSHKey(client, cfg.BackendURL, fp)
		if err != nil {
			log.Printf("ssh-key lookup error for %s: %v", fp, err)
			return false
		}

		var jwt string
		if found {
			// Known key — mint JWT via service token
			jwt, err = mintSessionJWT(client, cfg.BackendURL, cfg.ServiceToken, userID)
			if err != nil {
				log.Printf("session mint error for user %s: %v", userID, err)
				return false
			}
		} else {
			// Unknown key — create guest, then link SSH key
			jwt, userID, err = createGuestAndLinkKey(client, cfg.BackendURL, fp, key)
			if err != nil {
				log.Printf("guest creation error for %s: %v", fp, err)
				return false
			}
		}

		ctx.SetValue(ctxKeyJWT, jwt)
		ctx.SetValue(ctxKeyUserID, userID)
		log.Printf("SSH auth success: fp=%s user=%s", fp, userID)
		return true
	}
}

