	tests := []struct {
		name     string
		backend  string
		expected string
	}{
		{
			name:     "http_to_ws",
			backend:  "http://localhost:8099",
			expected: "ws://localhost:8099/ws",
		},
		{
			name:     "https_to_wss",
			backend:  "https://api.kinetik.example",
			expected: "wss://api.kinetik.example/ws",
		},
		{
			name:     "http_localhost_8080",
			backend:  "http://localhost:8080",
			expected: "ws://localhost:8080/ws",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			wsURL := tt.backend + "/ws"
			wsURL = strings.Replace(wsURL, "http://", "ws://", 1)
			wsURL = strings.Replace(wsURL, "https://", "wss://", 1)

			if wsURL != tt.expected {
				t.Errorf("got %q, want %q", wsURL, tt.expected)
			}
		})
	}
}

func TestWebSocketURLNoDoubleConversion(t *testing.T) {
