func RunSSHServer(cfg SSHServerConfig) error {
	handler := func(sess ssh.Session) (tea.Model, []tea.ProgramOption) {
		ctx := sess.Context()
		jwt, _ := ctx.Value(ctxKeyJWT).(string)
		fp, _ := ctx.Value(ctxKeyFingerprint).(string)

		// Get TERM from the SSH session
		term := ""
		if env := sess.Environ(); env != nil {
			for _, e := range env {
				if len(e) > 5 && e[:5] == "TERM=" {
					term = e[5:]
					break
				}
			}
		}

		model := NewRootModel(cfg.BackendURL, jwt, fp, term)
		return model, nil
	}

	srv, err := wish.NewServer(
		wish.WithAddress(cfg.Addr),
		wish.WithHostKeyPath(cfg.HostKeyPath),
		wish.WithPublicKeyAuth(makePublicKeyAuth(cfg)),
		wish.WithMiddleware(
			bubbletea.Middleware(handler),
			activeterm.Middleware(),
			logging.Middleware(),
		),
	)
	if err != nil {
		return fmt.Errorf("create ssh server: %w", err)
	}

	log.Printf("Kinetik TUI SSH server listening on %s (backend: %s)", cfg.Addr, cfg.BackendURL)
	return srv.ListenAndServe()
}

func main() {
	addr := flag.String("addr", ":2222", "SSH listen address")
	backend := flag.String("backend", "http://localhost:8080", "Backend HTTP URL")
	flag.Parse()

	cfg := DefaultSSHServerConfig()
	cfg.Addr = *addr
	cfg.BackendURL = *backend

	if cfg.ServiceToken == "" {
		log.Println("warning: KINETIK_TUI_SERVICE_TOKEN not set — SSH key auth will fail")
	}

	// Ensure host key directory exists
	if err := os.MkdirAll(filepath.Dir(cfg.HostKeyPath), 0700); err != nil {
		log.Printf("warning: could not create host key dir: %v", err)
	}

	if err := RunSSHServer(cfg); err != nil {
		log.Fatalf("server error: %v", err)
	}
}

