        # Clean up any existing connection before opening a new one
        if self._listen_task and not self._listen_task.done():
            self._listen_task.cancel()
            try:
                await self._listen_task
            except asyncio.CancelledError:
                pass
        if self.ws and not self.ws.closed:
            await self.ws.close()
        # Clear stale messages from the previous connection.
        # Without this, a "Connection closed" sentinel or leftover state messages
        # from the old connection would be returned by wait_for_state() on the new one.
        while not self._state_queue.empty():
            self._state_queue.get_nowait()
        self.state = None
        headers = {"Authorization": f"Bearer {self.token}"} if self.token else {}
