class PlayerSession:
    def __init__(self, ws, user: dict | None, game_manager):
        self.ws = ws
        self.user = user
        self.game_manager = game_manager
        self.room: GameRoom | SoloRoom | None = None
        self.queued = False

    async def handle_message(self, data: dict):
        msg_type = data.get("type")

        if msg_type == "play":
            await self.handle_play(data)
        elif msg_type == "cancel":
            await self.handle_cancel()
        elif msg_type == "tap":
            if self.room:
                await self.room.handle_tap(self.ws, data)
        elif msg_type == "rematch":
            if self.room:
                await self.room.handle_rematch(self.ws)
        elif msg_type == "leave":
            await self.handle_leave()
        else:
            await self.ws.send_json({"type": "error", "message": f"Unknown or missing message type: {msg_type}"})

    async def handle_play(self, data: dict):
        mode = data.get("mode")

        # Clean up any previous state before starting a new game
        if self.queued:
            self.game_manager.remove_from_queue(self.ws)
            self.queued = False
        if self.room:
            await self.room.handle_leave(self.ws)
