async def websocket_handler(request: web.Request):
    """WebSocket handler — single connection per player, handles full lifecycle.

    In production (DEBUG=false), the WebSocket is localhost-only — the TUI
    connects from the same host. In debug mode, external connections are
    allowed for development.
    """
    if not Config.DEBUG:
        peer = request.remote
        if peer and peer not in ("127.0.0.1", "::1", "localhost"):
            return web.Response(status=403, text="WebSocket access is restricted to localhost")

    if not acquire_ws_connection(request):
        return web.Response(status=429, text="Too many connections")

    ws = web.WebSocketResponse()
    await ws.prepare(request)

    game_manager: GameManager = request.app[GAME_MANAGER]
    user = get_or_create_guest_user(request)
    session = PlayerSession(ws, user, game_manager)

    game_manager.metrics.players_online += 1
    game_manager.update_metrics()

    try:
        async for msg in ws:
            if msg.type == web.WSMsgType.TEXT:
                try:
                    data = json.loads(msg.data)
                except json.JSONDecodeError:
                    await ws.send_json({"type": "error", "message": "Invalid JSON"})
                    continue
                if not isinstance(data, dict):
