    """Load .env file into os.environ using setdefault semantics.

    Shell env vars take priority over .env values. Called before
    applying --debug so that .env DEBUG value wins over the flag.
    """
    env_path = Path(__file__).parent.parent / ".env"
    if not env_path.exists():
