async def expire_queue_entries(self, max_wait_seconds: int = 90):
        """Remove queue entries that have been waiting longer than max_wait_seconds."""
        now = time.time()
        expired = [p for p in self.queue if now - p.queued_at > max_wait_seconds]
        self.queue = [p for p in self.queue if now - p.queued_at <= max_wait_seconds]
        for p in expired:
            if p.session:
                p.session.queued = False
            if not p.ws.closed:
                try:
                    await p.ws.send_json({"type": "error", "message": "Queue expired"})
                except Exception:
                    pass
            log.info("Expired queue entry for %s", p.username)

async def _periodic_cleanup(app: web.Application):
    """Periodically expire stale queue entries and clean up finished rooms."""
    game_manager: GameManager = app[GAME_MANAGER]
    while True:
        await asyncio.sleep(10)
        try:
            await game_manager.expire_queue_entries()
            # Clean up finished rooms with no human players
            empty = []
            for mid, room in game_manager.rooms.items():
                if room.status != "finished":
                    continue
                if not room.has_human_players():
                    empty.append(mid)
            for mid in empty:
                game_manager.remove_room(mid)
            if empty:
                log.debug("Cleaned up %d empty rooms", len(empty))
        except Exception as e:
            log.exception("Error during periodic cleanup: %s", e)

