    """Run all achievement rules against the latest match.

    match_data should contain: won, my_score, opponent_score, move_count,
    avg_reaction_time_ms, max_deficit, mode.

    For solo mode, match_data should also contain: session_score,
    longest_streak, duration_ms.

    Returns list of newly-earned achievements (key, name, description).
    """
    mode = match_data.get("mode", "duel")

    # Get stats for the mode — solo uses a different stats function.
    # skip_rank=True avoids an unnecessary COUNT query per achievement check.
    if mode == "solo":
        stats = get_solo_stats(conn, user_id, skip_rank=True)
    else:
        difficulty = match_data.get("difficulty")
        stats = get_player_stats(conn, user_id, mode, difficulty=difficulty, skip_rank=True)

    earned = []

    for key, rule in ACHIEVEMENTS.items():
        # Skip if achievement is mode-restricted and current mode doesn't match
        rule_modes = rule.get("modes")
        if rule_modes and mode not in rule_modes:
            continue

        try:
            if rule["check"](match_data, stats):
                if insert_achievement(conn, user_id, key):
                    earned.append({
                        "key": key,
                        "name": rule["name"],
                        "description": rule["description"],
                    })
